<?php
require '../config/config.php';role(['administrator','pustakawan']);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$uid=(int)($_POST['uid']??0);$cid=(int)($_POST['cid']??0);$memberCode=trim($_POST['member_code']??'');$copyCode=trim($_POST['copy_code']??'');
  if($memberCode){$q=$pdo->prepare("SELECT id FROM users WHERE username=? AND role='anggota' AND status='aktif'");$q->execute([$memberCode]);$uid=(int)$q->fetchColumn();if(!$uid)throw new Exception('Barcode anggota/NIS tidak ditemukan.');}
  if($copyCode){$q=$pdo->prepare("SELECT id FROM copies WHERE code=?");$q->execute([$copyCode]);$cid=(int)$q->fetchColumn();if(!$cid)throw new Exception('Barcode buku tidak ditemukan.');}
  if(!$uid||!$cid)throw new Exception('Pilih anggota dan eksemplar atau gunakan scan barcode.');
  $n=$pdo->prepare('SELECT COUNT(*) FROM loans WHERE user_id=? AND returned_at IS NULL');$n->execute([$uid]);$late=$pdo->prepare('SELECT COUNT(*) FROM loans WHERE user_id=? AND returned_at IS NULL AND due_date<CURDATE()');$late->execute([$uid]);$c=$pdo->prepare('SELECT status FROM copies WHERE id=?');$c->execute([$cid]);$cs=$c->fetchColumn();
  if($n->fetchColumn()>=setting('max_loans',2))setmsg('Batas buku anggota tercapai.','danger');elseif($late->fetchColumn())setmsg('Anggota memiliki buku terlambat.','danger');elseif($cs!=='tersedia')setmsg('Eksemplar tidak tersedia.','danger');else{$due=(new DateTime())->modify('+'.(int)setting('loan_days',7).' days')->format('Y-m-d');$pdo->prepare('INSERT INTO loans(user_id,copy_id,loan_date,due_date) VALUES(?,?,CURDATE(),?)')->execute([$uid,$cid,$due]);$pdo->prepare("UPDATE copies SET status='dipinjam' WHERE id=?")->execute([$cid]);setmsg("Berhasil dipinjam. Jatuh tempo: $due");}
 }catch(Throwable $e){setmsg($e->getMessage(),'danger');}
}
$m=$pdo->query("SELECT id,name,username FROM users WHERE role='anggota' AND status='aktif' ORDER BY name")->fetchAll();$c=$pdo->query("SELECT c.id,c.code,b.title FROM copies c JOIN books b ON b.id=c.book_id WHERE c.status='tersedia' ORDER BY b.title")->fetchAll();$l=$pdo->query("SELECT l.*,u.name,c.code,b.title FROM loans l JOIN users u ON u.id=l.user_id JOIN copies c ON c.id=l.copy_id JOIN books b ON b.id=c.book_id WHERE l.returned_at IS NULL ORDER BY l.due_date")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Peminjaman</title><link rel=stylesheet href=../public/style.css><style>.scanbox{background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:15px;margin-bottom:15px}.scan-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:700px){.scan-grid{grid-template-columns:1fr}}</style></head><body><div class=layout><?php include '../public/nav.php'?><main class=main><h1>🔄 Peminjaman</h1><?php msg()?><div class=scanbox><h3>⚡ Peminjaman Cepat dengan Barcode</h3><p>Scan <b>barcode anggota</b> (NIS/username pada kartu) lalu scan <b>barcode eksemplar buku</b>. Scanner USB dapat digunakan seperti keyboard.</p><form method=post><div class=scan-grid><div><label>Scan Barcode Anggota / NIS</label><input name=member_code autofocus placeholder="Contoh: 2026001"></div><div><label>Scan Barcode Buku</label><input name=copy_code placeholder="Contoh: BK-0001-01"></div></div><button>🔄 Proses Peminjaman</button></form></div><div class=form><h3>Peminjaman Manual</h3><form method=post><div class=grid><div><label>Anggota</label><select name=uid required><option value="">Pilih anggota</option><?php foreach($m as $x):?><option value=<?=$x['id']?>><?=e($x['name'])?> (<?=e($x['username'])?>)</option><?php endforeach?></select></div><div><label>Eksemplar</label><select name=cid required><option value="">Pilih eksemplar</option><?php foreach($c as $x):?><option value=<?=$x['id']?>><?=e($x['code'].' - '.$x['title'])?></option><?php endforeach?></select></div></div><button>Pinjam</button></form></div><br><table class=table><tr><th>Anggota</th><th>Buku</th><th>Jatuh Tempo</th><th>Status</th></tr><?php foreach($l as $x):?><tr><td><?=e($x['name'])?></td><td><?=e($x['code'].' - '.$x['title'])?></td><td><?=e($x['due_date'])?></td><td><?=$x['due_date']<date('Y-m-d')?'🔴 Terlambat':'🟢 Aktif'?></td></tr><?php endforeach?><?php if(!$l):?><tr><td colspan=4>Belum ada peminjaman aktif.</td></tr><?php endif?></table></main></div></body></html>
